  ('0c5837e9-86d1-5ea9-a26e-02a76417aef8', '3d67841a-f82f-571e-a56a-11f4d6ca997e', 10, 'FIZ', '10.1.3.1', 'Mıknatısların oluşturduğu manyetik alanı ve özelliklerini açıklar.', null, null, '10.1.3', 'KAZANIM', 51, 23, null),
