  ('068c8257-2b2f-5b69-9f6b-4dbeb40d5a4b', '3d67841a-f82f-571e-a56a-11f4d6ca997e', 10, 'FIZ', '10.3.1.2', 'Dalgaları taşıdığı enerjiye ve titreşim doğrultusuna göre sınıflandırır.', null, null, '10.3.1', 'KAZANIM', 59, 25, null),
  ('ca1d110d-e77e-5639-aec8-c8b1e8e60c7b', '3d67841a-f82f-571e-a56a-11f4d6ca997e', 10, 'FIZ', '10.3.2.1', 'Atma ve periyodik dalga oluşturarak aralarındaki farkı açıklar.', null, null, '10.3.2', 'KAZANIM', 60, 25, null),
