  ('ef84d23b-f433-5474-9b37-c7b5c51d1854', '7e94c6e6-07d1-5862-a946-e6cb96948a2b', 9, 'DIN', '9.2.1', 'Kaynağı ve unsurları bakımından din tanımlarını karşılaştırır.', null, null, '9.2', 'KAZANIM', 4, 23, null),
  ('80ec494d-d68d-58f7-82a4-f72077693130', '7e94c6e6-07d1-5862-a946-e6cb96948a2b', 9, 'DIN', '9.2.2', 'İnsanın doğası ile din arasında ilişki kurar.', null, null, '9.2', 'KAZANIM', 5, 23, null),
  ('ed70c481-652c-5233-bfe5-e8469e0fe61a', '7e94c6e6-07d1-5862-a946-e6cb96948a2b', 9, 'DIN', '9.2.3', 'İman ve İslam kavramları arasındaki ilişkiyi fark eder.', null, null, '9.2', 'KAZANIM', 6, 23, null),
  ('baae5680-efbe-5c7f-a69f-686875966d8a', '7e94c6e6-07d1-5862-a946-e6cb96948a2b', 9, 'DIN', '9.2.4', 'İslam’ın inanç esaslarının özelliklerini ayet ve hadisler ışığında analiz eder.', null, null, '9.2', 'KAZANIM', 7, 23, null),
  ('0b9069aa-b923-5622-ac7f-0e0e9618ed27', '7e94c6e6-07d1-5862-a946-e6cb96948a2b', 9, 'DIN', '9.2.5', 'Nisâ suresi 136. ayette verilen mesajları değerlendirir.', null, null, '9.2', 'KAZANIM', 8, 23, null),
  ('ea96c2fe-2d6c-5f02-9864-32c611e67952', '7e94c6e6-07d1-5862-a946-e6cb96948a2b', 9, 'DIN', '9.3.1', 'İslam’da ibadet kavramını ve ibadetin kapsamını açıklar.', null, null, '9.3', 'KAZANIM', 9, 24, null),
  ('146a08d9-5901-528e-9608-643d4abe58cb', '7e94c6e6-07d1-5862-a946-e6cb96948a2b', 9, 'DIN', '9.3.2', 'İslam’da ibadetlerin yapılış amacını ve önemini fark eder.', null, null, '9.3', 'KAZANIM', 10, 24, null),
  ('9a50b9f5-fb6e-5172-841e-93a65a673b06', '7e94c6e6-07d1-5862-a946-e6cb96948a2b', 9, 'DIN', '9.3.3', 'İbadet yükümlülüğü ile ilgili bazı kavramları sınıflandırır.', null, null, '9.3', 'KAZANIM', 11, 24, null),
  ('f256e8cf-4338-58a9-a73b-177c4b7f36d8', '7e94c6e6-07d1-5862-a946-e6cb96948a2b', 9, 'DIN', '9.3.4', 'İslam’da ibadetlerin temel ilkelerini değerlendirir.', null, null, '9.3', 'KAZANIM', 12, 24, null),
  ('f673e4c4-a70e-52cf-bb24-6bfc076942a6', '7e94c6e6-07d1-5862-a946-e6cb96948a2b', 9, 'DIN', '9.3.5', 'İbadetlerin, bireyin ahlaki gelişimi üzerindeki etkisini yorumlar.', null, null, '9.3', 'KAZANIM', 13, 24, null),
  ('247df049-f131-509b-8acf-80f0fa934ccb', '7e94c6e6-07d1-5862-a946-e6cb96948a2b', 9, 'DIN', '9.3.6', 'Bakara suresi 177. ayette verilen mesajları değerlendirir.', null, null, '9.3', 'KAZANIM', 14, 24, null),
  ('d00697ee-b38c-5cd2-9ca8-16d01baedbf2', '7e94c6e6-07d1-5862-a946-e6cb96948a2b', 9, 'DIN', '9.4.1', 'Değerlerin oluşumuna etki eden unsurları analiz eder.', null, null, '9.4', 'KAZANIM', 15, 25, null),
  ('45065822-7803-5002-9668-f6d25c664d23', '7e94c6e6-07d1-5862-a946-e6cb96948a2b', 9, 'DIN', '9.4.2', 'Gençlerin kişilik gelişiminde dinî ve ahlaki değerler ile örf ve âdetlerin yerini tartışır.', null, null, '9.4', 'KAZANIM', 16, 25, null),
  ('c4640f3b-2557-522f-ad67-5aea70517b61', '7e94c6e6-07d1-5862-a946-e6cb96948a2b', 9, 'DIN', '9.4.3', 'Temel değerleri ayet ve hadislerle ilişkilendirir.', null, null, '9.4', 'KAZANIM', 17, 25, null),
  ('136d128c-d382-5238-a044-44a5e7e6d658', '7e94c6e6-07d1-5862-a946-e6cb96948a2b', 9, 'DIN', '9.4.4', 'İsrâ suresi 23-29. ayetlerde verilen mesajları değerlendirir.', null, null, '9.4', 'KAZANIM', 18, 25, null),
  ('ddab97ff-d3cf-5214-abae-d69afc5040c0', '7e94c6e6-07d1-5862-a946-e6cb96948a2b', 9, 'DIN', '9.5.1', 'İslam medeniyeti kavramını izah eder.', null, null, '9.5', 'KAZANIM', 19, 26, null),
  ('eaee440c-f753-5542-97b4-d5d6c1d0589b', '7e94c6e6-07d1-5862-a946-e6cb96948a2b', 9, 'DIN', '9.5.2', 'İslam medeniyetinin, dünyanın farklı bölgelerindeki etkilerini fark eder.', null, null, '9.5', 'KAZANIM', 20, 26, null),
  ('494eeeec-c303-50e9-b59d-faaa3ec7c14c', '7e94c6e6-07d1-5862-a946-e6cb96948a2b', 9, 'DIN', '9.5.3', 'Hucurât suresi 13. ayette verilen mesajları değerlendirir.', null, null, '9.5', 'KAZANIM', 21, 26, null),
  ('0a304ec7-d4f9-57ae-afe9-c69f101afb36', '101895bd-2a32-5175-a21b-537c8eb54a07', 10, 'DIN', '10.1.1', 'Allah inancının insan hayatındaki yeri ve önemini yorumlar.', null, null, '10.1', 'KAZANIM', 22, 27, null),
  ('a543091f-154d-5d48-93da-04cee2ea905e', '101895bd-2a32-5175-a21b-537c8eb54a07', 10, 'DIN', '10.1.2', 'Allah’ın varlığı ve birliği konusunda akli ve naklî delilleri analiz eder.', null, null, '10.1', 'KAZANIM', 23, 27, null),
  ('4fde44db-f5d1-5524-a360-aa72d5ab80ff', '101895bd-2a32-5175-a21b-537c8eb54a07', 10, 'DIN', '10.1.3', 'İsim ve sıfatlarının yansımalarıyla Allah''ı tanır.', null, null, '10.1', 'KAZANIM', 24, 27, null),
  ('01d4d412-277f-5541-a578-3892cbdd446e', '101895bd-2a32-5175-a21b-537c8eb54a07', 10, 'DIN', '10.1.4', 'İnsanın özelliklerini ayetlerle açıklar.', null, null, '10.1', 'KAZANIM', 25, 27, null),
  ('d328e580-2e95-5666-8d72-52c14552246e', '101895bd-2a32-5175-a21b-537c8eb54a07', 10, 'DIN', '10.1.5', 'İnsanın Allah ile irtibat yollarını fark eder.', null, null, '10.1', 'KAZANIM', 26, 27, null),
  ('17f0afd4-9bcb-5a63-996d-4b103edce915', '101895bd-2a32-5175-a21b-537c8eb54a07', 10, 'DIN', '10.1.6', 'Rûm suresi 18-27. ayetlerde verilen mesajları değerlendirir.', null, null, '10.1', 'KAZANIM', 27, 27, null),
  ('e284f76e-94bc-59b2-bf48-228757c3382f', '101895bd-2a32-5175-a21b-537c8eb54a07', 10, 'DIN', '10.2.1', 'Kur’an-ı Kerim’den gençlerle ilgili ayetlere örnekler verir.', null, null, '10.2', 'KAZANIM', 28, 28, null),
  ('1d31249b-7108-5641-a6c6-83ae905a5f28', '101895bd-2a32-5175-a21b-537c8eb54a07', 10, 'DIN', '10.2.2', 'Hz. Muhammed''in gençlik yıllarındaki erdemli davranışlarını kendi hayatıyla ilişkilendirir.', null, null, '10.2', 'KAZANIM', 29, 28, null),
  ('fe576492-3ebe-535d-a732-aa639ebe75f4', '101895bd-2a32-5175-a21b-537c8eb54a07', 10, 'DIN', '10.2.3', 'Hz. Muhammed ile genç sahabiler arasındaki iletişimi değerlendirir.', null, null, '10.2', 'KAZANIM', 30, 28, null),
  ('d523cc5f-5edf-561d-a4bb-c90109f8dba1', '101895bd-2a32-5175-a21b-537c8eb54a07', 10, 'DIN', '10.2.4', 'Bazı genç sahabilerin öne çıkan özelliklerini örnek alır.', null, null, '10.2', 'KAZANIM', 31, 28, null),
  ('acd7110a-99c3-52ce-b06a-51839d2b66ca', '101895bd-2a32-5175-a21b-537c8eb54a07', 10, 'DIN', '10.2.5', 'Âl-i İmrân suresi 159. ayette verilen mesajları değerlendirir.', null, null, '10.2', 'KAZANIM', 32, 28, null),
  ('5ef8165e-21c6-50f5-9b45-1733c232ed7f', '101895bd-2a32-5175-a21b-537c8eb54a07', 10, 'DIN', '10.3.1', 'İslam dininin aile kurumuna verdiği önemi fark eder.', null, null, '10.3', 'KAZANIM', 33, 29, null),
  ('100cbc69-5db4-56c1-a1ee-572929f5e79f', '101895bd-2a32-5175-a21b-537c8eb54a07', 10, 'DIN', '10.3.2', 'İslam dininin kültür, sanat ve düşünce üzerindeki etkilerini analiz eder.', null, null, '10.3', 'KAZANIM', 34, 29, null),
  ('7773cf84-6476-5c74-ae28-66e9fdc22d31', '101895bd-2a32-5175-a21b-537c8eb54a07', 10, 'DIN', '10.3.3', 'İslam dininin çevre sorunlarına yaklaşımını ve çözüm önerilerini değerlendirir.', null, null, '10.3', 'KAZANIM', 35, 29, null),
  ('9d71172e-ab27-5135-8aad-56844181844a', '101895bd-2a32-5175-a21b-537c8eb54a07', 10, 'DIN', '10.3.4', 'İslam dini ve sosyal değişim arasında ilişki kurar.', null, null, '10.3', 'KAZANIM', 36, 29, null),
  ('e84598bd-3be9-5484-bdcb-48727f591f6e', '101895bd-2a32-5175-a21b-537c8eb54a07', 10, 'DIN', '10.3.5', 'İslam dininin ekonomik hayatla ilgili ilkelerini yorumlar.', null, null, '10.3', 'KAZANIM', 37, 29, null),
  ('61966d3d-bfb9-5275-96e1-a16190008ef3', '101895bd-2a32-5175-a21b-537c8eb54a07', 10, 'DIN', '10.3.6', 'İslam dininin sosyal adaletle ilgili ilkelerini açıklar.', null, null, '10.3', 'KAZANIM', 38, 29, null),
