  ('28d942ba-46bc-5ec3-8ecc-ebaa01fa5512', '101895bd-2a32-5175-a21b-537c8eb54a07', 10, 'DIN', '10.4.2', 'Ahlak ile terbiye arasındaki ilişki kurar.', null, null, '10.4', 'KAZANIM', 41, 30, null),
  ('21e3608c-8b94-5a1d-b20b-b2986af5008a', '101895bd-2a32-5175-a21b-537c8eb54a07', 10, 'DIN', '10.4.3', 'İslam ahlakında yerilen bazı davranışları ayet ve hadislerle açıklar.', null, null, '10.4', 'KAZANIM', 42, 30, null),
  ('4ac85422-6d07-5c3b-9752-a0bbe85eb233', '101895bd-2a32-5175-a21b-537c8eb54a07', 10, 'DIN', '10.4.4', 'Tutum ve davranışlarında ölçülü olmaya özen gösterir.', null, null, '10.4', 'KAZANIM', 43, 30, null),
