  ('32ba5166-eb07-5487-94af-b5eac8ba8e63', '101895bd-2a32-5175-a21b-537c8eb54a07', 10, 'DIN', '10.5.2', 'İslam düşüncesindeki yorum farklılıklarının sebeplerini tartışır.', null, null, '10.5', 'KAZANIM', 46, 31, null),
  ('6fb055e8-b81c-57d8-8c83-dcc7806f0163', '101895bd-2a32-5175-a21b-537c8eb54a07', 10, 'DIN', '10.5.3', 'Dinî yorumlarla ilgili bazı kavramları değerlendirir.', null, null, '10.5', 'KAZANIM', 47, 31, null),
  ('3c40a191-d55d-5f5a-ad12-da576036438b', '101895bd-2a32-5175-a21b-537c8eb54a07', 10, 'DIN', '10.5.4', 'İslam düşüncesinde itikadi ve siyasi yorumları genel özelliklerine göre sınıflandırır.', null, null, '10.5', 'KAZANIM', 48, 31, null),
  ('71064d37-ebc2-5d47-8277-dda04155f286', '101895bd-2a32-5175-a21b-537c8eb54a07', 10, 'DIN', '10.5.5', 'İslam düşüncesindeki amelî fıkhi yorumları tanır.', null, null, '10.5', 'KAZANIM', 49, 31, null),
